1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	import { validateImageBytes, MAX_ATTACHMENT_BYTES } from "@/lib/chat-attachment";
6	
7	export const runtime = "nodejs";
8	
9	/**
10	 * Image upload for <ChatWidget/>.
11	 *
12	 * POST /api/chat/upload  (multipart/form-data: visitorId, file, optional body,
13	 * optional name/email) — attaches an image to the visitor's OPEN conversation
14	 * (created if none), exactly like POST /api/chat but carrying an image.
15	 *
16	 * Authorization mirrors POST /api/chat: the conversation is scoped strictly by
17	 * the client-supplied `visitorId`, so a visitor can only ever attach to their
18	 * own thread. The image is validated by signature (not the client-declared
19	 * type) in lib/chat-attachment — SVG and non-images are rejected. Bytes live in
20	 * Postgres. Per-IP rate limited.
21	 */
22	
23	function clientIp(req: Request): string {
24	  const xff = req.headers.get("x-forwarded-for") ?? "";
25	  const first = xff.split(",")[0]?.trim();
26	  return first || "unknown";
27	}
28	
29	function clip(v: unknown, max: number): string | null {
30	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
31	}
32	
33	export async function POST(req: Request) {
34	  const rl = checkRateLimit(`chat-upload:${clientIp(req)}`, { max: 15, windowMs: 60_000 });
35	  if (!rl.ok) {
36	    return NextResponse.json(
37	      { error: "Too many uploads. Please slow down." },
38	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
39	    );
40	  }
41	
42	  let form: FormData;
43	  try {
44	    form = await req.formData();
45	  } catch {
46	    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
47	  }
48	
49	  const visitorId = clip(form.get("visitorId"), 100);
50	  const body = clip(form.get("body"), 5000) ?? "";
51	  const name = clip(form.get("name"), 120);
52	  const email = clip(form.get("email"), 200);
53	  const file = form.get("file");
54	
55	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
56	  if (!(file instanceof File)) return NextResponse.json({ error: "No image provided." }, { status: 400 });
57	  // Cheap guard before buffering the whole body into memory.
58	  if (file.size > MAX_ATTACHMENT_BYTES) {
59	    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
60	  }
61	
62	  const bytes = Buffer.from(await file.arrayBuffer());
63	  const check = validateImageBytes(bytes, file.type);
64	  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });
65	
66	  const user = await currentUser();
67	
68	  // Continue the visitor's existing open conversation, else start a new one.
69	  let convo = await db.chatConversation.findFirst({
70	    where: { visitorId, status: "OPEN" },
71	    orderBy: { lastMessageAt: "desc" },
72	    select: { id: true, name: true, email: true },
73	  });
74	
75	  if (!convo) {
76	    convo = await db.chatConversation.create({
77	      data: {
78	        visitorId,
79	        userId: user?.id ?? null,
80	        name: name ?? user?.name ?? null,
81	        email: email ?? user?.email ?? null,
82	      },
83	      select: { id: true, name: true, email: true },
84	    });
85	  }
86	
87	  const convoId = convo.id;
88	  await db.$transaction(async (tx) => {
89	    const msg = await tx.chatMessage.create({
90	      data: { conversationId: convoId, sender: "visitor", body },
91	    });
92	    await tx.chatAttachment.create({
93	      data: {
94	        messageId: msg.id,
95	        mime: check.mime,
96	        sizeBytes: check.bytes.length,
97	        data: new Uint8Array(check.bytes),
98	      },
99	    });
100	    await tx.chatConversation.update({
101	      where: { id: convoId },
102	      data: {
103	        unreadForAgent: true,
104	        lastMessageAt: new Date(),
105	        ...(user?.id ? { userId: user.id } : {}),
106	        ...(name && !convo!.name ? { name } : {}),
107	        ...(email && !convo!.email ? { email } : {}),
108	      },
109	    });
110	  });
111	
112	  const full = await db.chatConversation.findUnique({
113	    where: { id: convoId },
114	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
115	  });
116	
117	  return NextResponse.json({
118	    conversation: full
119	      ? { id: full.id, status: full.status, name: full.name, email: full.email }
120	      : null,
121	    messages: (full?.messages ?? []).map((m) => ({
122	      id: m.id,
123	      sender: m.sender,
124	      body: m.body,
125	      createdAt: m.createdAt.toISOString(),
126	      attachment: m.attachment
127	        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
128	        : null,
129	    })),
130	  });
131	}
