1	/**
2	 * Security core for live-chat image attachments.
3	 *
4	 * Everything the upload paths (customer widget route + admin server action) and
5	 * the serving route agree on lives here: the allow-list, the size cap, and —
6	 * critically — the magic-number sniffer that validates the *real bytes* rather
7	 * than trusting the client-declared Content-Type. SVG is intentionally absent
8	 * from the allow-list AND has no binary signature, so it is rejected twice over
9	 * (SVG can carry <script> and would enable stored XSS if ever served).
10	 */
11	
12	/** The only image types we accept. `image/svg+xml` is deliberately excluded. */
13	export const ALLOWED_IMAGE_MIME = [
14	  "image/png",
15	  "image/jpeg",
16	  "image/gif",
17	  "image/webp",
18	] as const;
19	
20	export type AllowedImageMime = (typeof ALLOWED_IMAGE_MIME)[number];
21	
22	/** Hard cap: 5 MB. Enforced server-side regardless of any client check. */
23	export const MAX_ATTACHMENT_BYTES = 5 * 1024 * 1024;
24	
25	/** `accept` attribute value shared by the file inputs. */
26	export const ACCEPT_ATTR = ALLOWED_IMAGE_MIME.join(",");
27	
28	export function isAllowedImageMime(mime: string): mime is AllowedImageMime {
29	  return (ALLOWED_IMAGE_MIME as readonly string[]).includes(mime);
30	}
31	
32	/**
33	 * Detect the true image type from the leading bytes (file signature). Returns
34	 * the canonical MIME for a recognised, allowed image, or `null` for anything
35	 * else — including SVG, HTML, scripts, or a JPEG renamed to .png. Callers must
36	 * treat `null` as "reject".
37	 */
38	export function sniffImageMime(buf: Uint8Array): AllowedImageMime | null {
39	  if (buf.length < 12) return null;
40	  const b = buf;
41	
42	  // PNG: 89 50 4E 47 0D 0A 1A 0A
43	  if (
44	    b[0] === 0x89 &&
45	    b[1] === 0x50 &&
46	    b[2] === 0x4e &&
47	    b[3] === 0x47 &&
48	    b[4] === 0x0d &&
49	    b[5] === 0x0a &&
50	    b[6] === 0x1a &&
51	    b[7] === 0x0a
52	  ) {
53	    return "image/png";
54	  }
55	
56	  // JPEG: FF D8 FF
57	  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) {
58	    return "image/jpeg";
59	  }
60	
61	  // GIF: "GIF87a" / "GIF89a" — check "GIF8"
62	  if (b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x38) {
63	    return "image/gif";
64	  }
65	
66	  // WEBP: "RIFF" .... "WEBP"
67	  if (
68	    b[0] === 0x52 &&
69	    b[1] === 0x49 &&
70	    b[2] === 0x46 &&
71	    b[3] === 0x46 &&
72	    b[8] === 0x57 &&
73	    b[9] === 0x45 &&
74	    b[10] === 0x42 &&
75	    b[11] === 0x50
76	  ) {
77	    return "image/webp";
78	  }
79	
80	  return null;
81	}
82	
83	export type AttachmentValidation =
84	  | { ok: true; mime: AllowedImageMime; bytes: Buffer }
85	  | { ok: false; error: string };
86	
87	/**
88	 * Full server-side validation of an uploaded image. Enforces, in order:
89	 *  1. non-empty,
90	 *  2. size ≤ 5 MB,
91	 *  3. declared MIME (if provided) is in the allow-list and is not SVG,
92	 *  4. the real bytes match an allowed signature AND agree with the declared
93	 *     type — the authoritative check; the stored MIME is the *sniffed* one.
94	 */
95	export function validateImageBytes(
96	  bytes: Buffer | Uint8Array,
97	  declaredMime?: string | null
98	): AttachmentValidation {
99	  const buf = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);
100	
101	  if (buf.length === 0) return { ok: false, error: "Empty file." };
102	  if (buf.length > MAX_ATTACHMENT_BYTES) {
103	    return { ok: false, error: "Image is larger than 5 MB." };
104	  }
105	
106	  const declared = (declaredMime ?? "").split(";")[0]?.trim().toLowerCase() || null;
107	  if (declared) {
108	    if (declared === "image/svg+xml") {
109	      return { ok: false, error: "SVG images are not allowed." };
110	    }
111	    if (!isAllowedImageMime(declared)) {
112	      return { ok: false, error: "Unsupported image type." };
113	    }
114	  }
115	
116	  const sniffed = sniffImageMime(buf);
117	  if (!sniffed) {
118	    return { ok: false, error: "File is not a supported image (PNG, JPEG, GIF, or WEBP)." };
119	  }
120	  if (declared && declared !== sniffed) {
121	    return { ok: false, error: "Image contents do not match its declared type." };
122	  }
123	
124	  return { ok: true, mime: sniffed, bytes: buf };
125	}
