1	// HTML sanitisation + text-preview helpers for the native webmail client.
2	//
3	// This is a plain server-side module (no "use server"): it is imported by the
4	// IMAP engine and the mail server actions to sanitise message bodies before
5	// they ever reach the client. `safeHtml` is DEFENCE IN DEPTH — the UI additionally
6	// renders the returned markup inside a sandboxed <iframe> — but we still strip the
7	// obvious script/exfiltration vectors here so a raw body never ships un-neutered.
8	
9	const DANGEROUS_WITH_CONTENT = /<(script|style|iframe|object|embed|noscript|template|frameset|frame|applet)\b[\s\S]*?<\/\1\s*>/gi;
10	const DANGEROUS_STANDALONE =
11	  /<\/?(script|style|iframe|object|embed|noscript|template|frameset|frame|applet|link|meta|base|form)\b[^>]*>/gi;
12	
13	// Attributes whose value can carry a navigable/loadable URL.
14	const URL_ATTRS = "href|src|xlink:href|action|formaction|background|poster|data|srcset";
15	// Schemes we never allow in those attributes.
16	const BAD_SCHEME = /^\s*(?:javascript|vbscript|data|blob|file)\s*:/i;
17	
18	/**
19	 * Sanitise an untrusted HTML email body. Removes:
20	 *  - <script>/<style>/<iframe>/<object>/<embed> (and similar) elements + content
21	 *  - inline event handlers (on*=…)
22	 *  - javascript:/vbscript:/data:/blob:/file: URLs in link/src-style attributes
23	 * Returns "" for null/empty input. Never throws.
24	 */
25	export function safeHtml(html: string | null | undefined): string {
26	  if (!html) return "";
27	  let out = String(html);
28	
29	  // 1) Drop dangerous elements together with their contents (handles nested too
30	  // because the pattern is non-greedy and re-run until stable).
31	  let prev: string;
32	  do {
33	    prev = out;
34	    out = out.replace(DANGEROUS_WITH_CONTENT, "");
35	  } while (out !== prev);
36	
37	  // 2) Remove any leftover standalone dangerous / layout-breaking tags.
38	  out = out.replace(DANGEROUS_STANDALONE, "");
39	
40	  // 3) Strip inline event handlers in all quoting styles.
41	  out = out.replace(/\son[a-z0-9_-]+\s*=\s*"[^"]*"/gi, "");
42	  out = out.replace(/\son[a-z0-9_-]+\s*=\s*'[^']*'/gi, "");
43	  out = out.replace(/\son[a-z0-9_-]+\s*=\s*[^\s>]+/gi, "");
44	
45	  // 4) Neutralise dangerous URL schemes in navigable/loadable attributes.
46	  const attr = new RegExp(`\\s(${URL_ATTRS})\\s*=\\s*("([^"]*)"|'([^']*)'|([^\\s>]+))`, "gi");
47	  out = out.replace(attr, (match, name: string, _all: string, dq?: string, sq?: string, uq?: string) => {
48	    const value = dq ?? sq ?? uq ?? "";
49	    if (BAD_SCHEME.test(decodeAttr(value))) return ` ${name}="#"`;
50	    return match;
51	  });
52	
53	  return out;
54	}
55	
56	// Decode the handful of entity/whitespace tricks used to smuggle "javascript:"
57	// past a naive scheme check (e.g. "java&#115;cript:", "java\tscript:").
58	function decodeAttr(v: string): string {
59	  return v
60	    .replace(/&#x([0-9a-f]+);?/gi, (_, h) => safeFromCodePoint(parseInt(h, 16)))
61	    .replace(/&#(\d+);?/g, (_, d) => safeFromCodePoint(parseInt(d, 10)))
62	    .replace(/[\s�-]+/g, "");
63	}
64	
65	function safeFromCodePoint(code: number): string {
66	  if (!Number.isFinite(code) || code < 0 || code > 0x10ffff) return "";
67	  try {
68	    return String.fromCodePoint(code);
69	  } catch {
70	    return "";
71	  }
72	}
73	
74	const ENTITIES: Record<string, string> = {
75	  "&nbsp;": " ",
76	  "&amp;": "&",
77	  "&lt;": "<",
78	  "&gt;": ">",
79	  "&quot;": '"',
80	  "&#39;": "'",
81	  "&apos;": "'",
82	  "&mdash;": "—",
83	  "&ndash;": "–",
84	  "&hellip;": "…",
85	};
86	
87	function decodeEntities(text: string): string {
88	  return text
89	    .replace(/&(?:nbsp|amp|lt|gt|quot|#39|apos|mdash|ndash|hellip);/g, (m) => ENTITIES[m] ?? m)
90	    .replace(/&#x([0-9a-f]+);/gi, (_, h) => safeFromCodePoint(parseInt(h, 16)))
91	    .replace(/&#(\d+);/g, (_, d) => safeFromCodePoint(parseInt(d, 10)));
92	}
93	
94	/**
95	 * Produce a compact (~140-char) plaintext snippet from an HTML or plaintext
96	 * body, suitable for a message-list preview. Strips markup, collapses
97	 * whitespace, decodes common entities, and adds an ellipsis when truncated.
98	 */
99	export function previewText(source: string | null | undefined, max = 140): string {
100	  if (!source) return "";
101	  let text = String(source);
102	  // Remove script/style blocks with their content so we never leak CSS/JS text.
103	  text = text.replace(/<(script|style)\b[\s\S]*?<\/\1\s*>/gi, " ");
104	  // Turn block boundaries into spaces, then strip remaining tags.
105	  text = text.replace(/<(?:br|\/p|\/div|\/tr|\/li|\/h[1-6])\b[^>]*>/gi, " ");
106	  text = text.replace(/<[^>]+>/g, " ");
107	  text = decodeEntities(text);
108	  text = text.replace(/\s+/g, " ").trim();
109	  if (text.length <= max) return text;
110	  return text.slice(0, max).replace(/\s+\S*$/, "").trimEnd() + "…";
111	}
