1	import { db } from "@/lib/db";
2	
3	/**
4	 * DB-backed email rendering + the shared branded email shell.
5	 *
6	 * Templates live in the `EmailTemplate` table (admin-editable). Each row stores
7	 * a `subject` and an HTML *body* containing `{{variable}}` placeholders. At send
8	 * time we load the row, substitute the variables, and wrap the body in the
9	 * shared branded shell (header/footer). If a template is missing or disabled we
10	 * fall back to a minimal built-in default so a send never silently produces an
11	 * empty email.
12	 *
13	 * DESIGN (2026 refresh): a light, deliverability-safe theme. Real-world inbox
14	 * data shows light emails land in the primary tab more reliably than dark ones,
15	 * so the body is a soft violet-tinted background with a white content card and a
16	 * violet accent header carrying the Nxeon wordmark. Everything is table-based
17	 * with fully inline styles — Gmail/Outlook/Apple-Mail strip <style>, flexbox and
18	 * external CSS, so none of those are used. Gradients degrade to a solid
19	 * `background-color` fallback in clients that drop `background-image`.
20	 *
21	 * This module has NO dependency on `lib/mailer.ts` (mailer depends on it), which
22	 * keeps the import graph acyclic.
23	 */
24	
25	/** Brand palette — violet primary (#8a70fb / #6f47f5) on a light, navy-ink card. */
26	export const BRAND = {
27	  // Header / primary accent
28	  violet: "#6f47f5",
29	  violetLight: "#8a70fb",
30	  violetDeep: "#5f2ee8",
31	  // Surfaces
32	  pageBg: "#eef0f8",
33	  card: "#ffffff",
34	  panel: "#f6f5fd",
35	  panelBorder: "#e7e3f7",
36	  hair: "#ecebf3",
37	  // Ink
38	  ink: "#1c1638",
39	  body: "#4a4763",
40	  muted: "#8a86a3",
41	  faint: "#a7a4bd",
42	  // Status
43	  success: "#15a34a",
44	  successBg: "#e9f8ef",
45	  warn: "#c2790b",
46	  warnBg: "#fdf3e3",
47	  danger: "#dc2626",
48	  dangerBg: "#fdecec",
49	  info: "#6f47f5",
50	  infoBg: "#f1edfe",
51	};
52	const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
53	
54	export function appUrl(): string {
55	  return process.env.APP_URL ?? "https://nxeon.cloud";
56	}
57	
58	const esc = (s: unknown) =>
59	  String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
60	
61	// ---------------------------------------------------------------------------
62	// Reusable, fully-inline email components. Every template composes these so the
63	// look stays consistent. All return an HTML string.
64	// ---------------------------------------------------------------------------
65	
66	export type Accent = "violet" | "success" | "warn" | "danger" | "info";
67	const accentColor = (a: Accent = "violet") =>
68	  a === "success" ? BRAND.success : a === "warn" ? BRAND.warn : a === "danger" ? BRAND.danger : BRAND.violet;
69	const accentBg = (a: Accent = "violet") =>
70	  a === "success" ? BRAND.successBg : a === "warn" ? BRAND.warnBg : a === "danger" ? BRAND.dangerBg : BRAND.infoBg;
71	
72	/** Small uppercase eyebrow/kicker label above the headline. */
73	export function emailEyebrow(text: string, accent: Accent = "violet"): string {
74	  return `<div style="margin:0 0 12px;font-family:${FONT};font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:${accentColor(accent)};">${esc(text)}</div>`;
75	}
76	
77	/** Main headline. */
78	export function emailHeading(text: string): string {
79	  return `<h1 style="margin:0 0 14px;font-family:${FONT};font-size:23px;line-height:1.3;font-weight:700;color:${BRAND.ink};">${esc(text)}</h1>`;
80	}
81	
82	/** Body paragraph. `html` may contain trusted inline markup (links, <b>). */
83	export function emailParagraph(html: string): string {
84	  return `<p style="margin:0 0 16px;font-family:${FONT};font-size:15px;line-height:1.65;color:${BRAND.body};">${html}</p>`;
85	}
86	
87	/** Small muted note (fine print, alternate-link fallback, etc). */
88	export function emailNote(html: string): string {
89	  return `<p style="margin:16px 0 0;font-family:${FONT};font-size:13px;line-height:1.6;color:${BRAND.muted};">${html}</p>`;
90	}
91	
92	/** Bulletproof CTA button (VML-free but padding-based so it survives Outlook). */
93	export function emailButton(href: string, label: string, accent: Accent = "violet"): string {
94	  const bg = accentColor(accent);
95	  const grad = accent === "violet" ? `background-image:linear-gradient(90deg,${BRAND.violet},${BRAND.violetLight});` : "";
96	  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 6px;"><tr><td align="center" style="border-radius:12px;background-color:${bg};${grad}">
97	    <a href="${href}" style="display:inline-block;padding:14px 34px;font-family:${FONT};font-size:15px;font-weight:600;line-height:1;color:#ffffff;text-decoration:none;border-radius:12px;">${esc(label)}</a>
98	  </td></tr></table>`;
99	}
100	
101	/** Soft rounded panel used to frame a details table / highlighted content. */
102	export function emailPanel(innerHtml: string, accent?: Accent): string {
103	  const border = accent ? accentColor(accent) : BRAND.panelBorder;
104	  const leftRule = accent ? `border-left:4px solid ${accentColor(accent)};` : `border:1px solid ${BRAND.panelBorder};`;
105	  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 18px;background-color:${BRAND.panel};${leftRule}border-radius:12px;">
106	    <tr><td style="padding:18px 20px;">${innerHtml}</td></tr></table>`;
107	}
108	
109	/** Colored status banner (e.g. suspended / payment failed / success). */
110	export function emailBanner(html: string, accent: Accent = "info"): string {
111	  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 18px;background-color:${accentBg(accent)};border-radius:12px;border-left:4px solid ${accentColor(accent)};">
112	    <tr><td style="padding:14px 18px;font-family:${FONT};font-size:14px;line-height:1.55;color:${BRAND.ink};font-weight:600;">${html}</td></tr></table>`;
113	}
114	
115	/** Key/value details table (two columns, hairline rows). Values may hold markup. */
116	export function emailKeyValue(rows: Array<[string, string]>): string {
117	  const body = rows
118	    .map(
119	      ([k, v], i) =>
120	        `<tr>
121	          <td style="padding:11px 0;${i ? `border-top:1px solid ${BRAND.hair};` : ""}font-family:${FONT};font-size:13px;color:${BRAND.muted};vertical-align:top;white-space:nowrap;">${esc(k)}</td>
122	          <td align="right" style="padding:11px 0 11px 16px;${i ? `border-top:1px solid ${BRAND.hair};` : ""}font-family:${FONT};font-size:14px;font-weight:600;color:${BRAND.ink};vertical-align:top;">${v}</td>
123	        </tr>`
124	    )
125	    .join("");
126	  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${body}</table>`;
127	}
128	
129	/** Monospace code / command block (e.g. an SSH command). */
130	export function emailCode(text: string): string {
131	  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 18px;background-color:#1c1638;border-radius:10px;">
