185	/** Replace `{{ var }}` placeholders with values from `vars` (missing → empty). */
186	export function substitute(input: string, vars: Record<string, unknown>): string {
187	  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key: string) => {
188	    const v = vars[key];
189	    return v === undefined || v === null ? "" : String(v);
190	  });
191	}
