193	/**
194	 * Minimal built-in defaults used when a template row is missing or disabled.
195	 * These are intentionally plain — the real, branded copy lives in the DB (see
196	 * `prisma/seed-email-templates.ts`).
197	 */
198	const DEFAULTS: Record<string, { subject: string; body: string }> = {
199	  welcome: {
200	    subject: "Welcome to Nxeon",
201	    body: `${emailHeading("Welcome, {{name}}!")}${emailParagraph("Your Nxeon account is ready. Deploy your first NVMe VPS in minutes.")}`,
202	  },
