205	    body: `${emailHeading("Reset your password")}${emailParagraph("Use the button below to set a new password. It expires in 1 hour.")}${emailButton("{{resetUrl}}", "Reset password")}`,
206	  },
207	};
208	
209	const GENERIC_FALLBACK = (key: string) => ({
210	  subject: "A message from Nxeon",
211	  body: `${emailHeading("Nxeon")}${emailParagraph(`This notification (<code>${esc(key)}</code>) has no configured template.`)}`,
212	});
