251	/**
252	 * Render a *draft* (unsaved) subject/body with sample vars — used by the admin
253	 * editor's live preview and by the seed preview. Same wrapping as a real send.
254	 */
255	export function renderDraft(subject: string, body: string, vars: Record<string, unknown> = {}): RenderedEmail {
256	  const preheader = typeof vars.preheader === "string" ? (vars.preheader as string) : undefined;
257	  return {
258	    template: "draft",
259	    subject: substitute(subject, vars),
260	    html: wrapEmail(substitute(body, vars), { preheader }),
261	  };
262	}
