278	function plainToHtml(plain: string): string {
279	  const esc = plain.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
280	  return `<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;color:#334155">${esc.replace(/\n/g, "<br>")}</div>`;
281	}
