303	  const [saving, setSaving] = useState(false);
304	  const [msg, setMsg] = useState<string | null>(null);
305	  const [err, setErr] = useState<string | null>(null);
306	
307	  // Seed the contentEditable once (React never re-writes it, so the caret is safe).
308	  useEffect(() => {
309	    if (editorRef.current) editorRef.current.innerHTML = seedHtml;
310	    // eslint-disable-next-line react-hooks/exhaustive-deps
311	  }, []);
312	
313	  const sync = useCallback(() => setHtml(editorRef.current?.innerHTML ?? ""), []);
314	
315	  const saveSel = useCallback(() => {
316	    const sel = window.getSelection();
317	    if (sel && sel.rangeCount > 0) {
318	      const r = sel.getRangeAt(0);
319	      if (editorRef.current && editorRef.current.contains(r.commonAncestorContainer)) {
320	        savedRange.current = r.cloneRange();
321	      }
322	    }
323	  }, []);
324	
325	  const restoreSel = useCallback(() => {
326	    const el = editorRef.current;
327	    if (!el) return;
328	    el.focus();
329	    const sel = window.getSelection();
330	    if (savedRange.current && sel) {
331	      try {
332	        sel.removeAllRanges();
333	        sel.addRange(savedRange.current);
334	      } catch {
335	        /* range detached — leave caret where it is */
336	      }
337	    }
338	  }, []);
339	
340	  // Run an execCommand, degrading gracefully if the browser doesn't support it.
341	  const exec = useCallback(
342	    (cmd: string, value?: string) => {
343	      try {
344	        restoreSel();
345	        document.execCommand(cmd, false, value);
346	      } catch {
347	        /* unsupported command — ignore rather than crash the editor */
348	      }
349	      saveSel();
350	      sync();
351	    },
352	    [restoreSel, saveSel, sync],
353	  );
