355	  const insertHtml = useCallback(
356	    (fragment: string) => {
357	      const el = editorRef.current;
358	      if (!el) return;
359	      restoreSel();
360	      let ok = false;
361	      try {
362	        ok = document.execCommand("insertHTML", false, fragment);
363	      } catch {
364	        ok = false;
365	      }
366	      if (!ok) el.innerHTML = el.innerHTML + fragment; // fallback: append
367	      saveSel();
368	      sync();
369	    },
370	    [restoreSel, saveSel, sync],
371	  );
