789	function fmtBytes(n: number): string {
790	  if (!Number.isFinite(n) || n <= 0) return "0 MB";
791	  const units = ["B", "KB", "MB", "GB", "TB"];
792	  let v = n;
793	  let i = 0;
794	  while (v >= 1024 && i < units.length - 1) {
795	    v /= 1024;
796	    i++;
797	  }
798	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
799	}
