801	function StorageSection({
802	  initial,
803	  usedBytes,
804	  quotaBytes,
805	}: {
806	  initial: MailboxSettings;
807	  usedBytes?: number;
808	  quotaBytes?: number;
809	}) {
810	  const quota =
811	    quotaBytes && quotaBytes > 0
812	      ? quotaBytes
813	      : initial.quotaMB
814	        ? initial.quotaMB * 1024 * 1024
815	        : 0;
816	  const used = usedBytes && usedBytes > 0 ? usedBytes : 0;
817	  const haveUsage = usedBytes !== undefined;
818	  const pct = quota > 0 ? Math.min(100, Math.round((used / quota) * 100)) : 0;
819	  const nearFull = pct >= 90;
820	
821	  return (
822	    <div className="space-y-5">
823	      <SectionHead title="Storage" sub="How much of this mailbox's quota is in use." />
824	
825	      <div className="rounded-2xl border border-white/[0.08] bg-white/[0.02] p-5">
826	        <div className="flex items-baseline justify-between">
827	          <span className="text-2xl font-semibold text-white">{fmtBytes(used)}</span>
828	          <span className="text-sm text-slate-400">of {quota > 0 ? fmtBytes(quota) : "—"}</span>
829	        </div>
830	
831	        <div className="mt-3 h-2.5 w-full overflow-hidden rounded-full bg-white/10">
832	          <div
833	            className={`h-full rounded-full ${nearFull ? "bg-gradient-to-r from-amber-400 to-red-400" : "bg-gradient-to-r from-accent-blue to-brand-500"}`}
834	            style={{ width: `${quota > 0 ? pct : 0}%` }}
835	          />
836	        </div>
837	
838	        <p className="mt-2 text-xs text-slate-500">
839	          {quota > 0 ? `${pct}% used` : "Quota not set"}
840	          {!haveUsage && " — live usage is unavailable right now; showing your plan quota."}
841	          {nearFull && haveUsage && " — you're running low. Clear out large messages or upgrade your plan."}
842	        </p>
843	      </div>
844	    </div>
845	  );
