898	
899	  const load = useCallback(async () => {
900	    setLoadErr(null);
901	    try {
902	      const res = await listAliases(mailboxAddress);
903	      if (!res.ok) {
904	        setLoadErr(res.error || "Couldn't load aliases.");
905	        setAliases([]);
906	      } else {
907	        setAliases(res.aliases);
908	      }
909	    } catch (e) {
910	      setLoadErr(e instanceof Error ? e.message : "Couldn't load aliases.");
911	      setAliases([]);
