939	    setErr(null);
940	    // Optimistic removal.
941	    setAliases((cur) => (cur ? cur.filter((a) => a.id !== id) : cur));
942	    try {
943	      const res = await removeAlias(id, mailboxAddress);
944	      if (!res.ok) {
945	        setErr(res.error || "Couldn't remove alias.");
946	        await load();
947	      }
948	    } catch (e) {
949	      setErr(e instanceof Error ? e.message : "Couldn't remove alias.");
