async function onImageFile(e: React.ChangeEvent<HTMLInputElement>) {
  const file = e.target.files?.[0];
  e.target.value = ""; // allow re-picking the same file later
  if (!file) return;

  setImgErr(null);
  setUploading(true);
  try {
    const body = new FormData();
    body.append("file", file);
    const res = await fetch("/api/mail/signature-image", { method: "POST", body });
    const data = (await res.json().catch(() => ({}))) as { url?: string; error?: string };
    if (!res.ok || !data.url) {
      setImgErr(data.error || "Couldn't upload that image.");
      return;
    }
    // Insert at the saved caret so the dialog's focus loss doesn't drop it.
    insertHtml(`<img src="${escAttr(data.url)}" style="max-width:100%" />`);
  } catch {
    setImgErr("Couldn't upload that image. Please try again.");
  } finally {
    setUploading(false);
  }
}

/** Escape a value for safe interpolation into a double-quoted HTML attribute. */
function escAttr(v: string): string {
  return v
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

